using Azure.Messaging.ServiceBus;using EnterpriseDocumentIntelligence.BuildingBlocks.Infrastructure;using EnterpriseDocumentIntelligence.BuildingBlocks.Messaging;using System.Text.Json;
public sealed class ServiceBusClientFactory(IConfiguration c){readonly ServiceBusClient client=!string.IsNullOrWhiteSpace(c["ServiceBus:ConnectionString"])?new(c["ServiceBus:ConnectionString"]!):new(c["ServiceBus:FullyQualifiedNamespace"]!,new Azure.Identity.DefaultAzureCredential());public ServiceBusProcessor Create(string t,string s)=>client.CreateProcessor(t,s,new ServiceBusProcessorOptions{MaxConcurrentCalls=8,PrefetchCount=50,AutoCompleteMessages=false});}
public sealed class Worker(ServiceBusClientFactory factory,ResilientEmbeddingService embeddings,IMessagePublisher publisher,ILogger<Worker> log):BackgroundService{protected override async Task ExecuteAsync(CancellationToken ct){var p=factory.Create(Topics.ProcessingEvents,"embedding-sub");p.ProcessMessageAsync+=Handle;p.ProcessErrorAsync+=Error;await p.StartProcessingAsync(ct);try{await Task.Delay(Timeout.Infinite,ct);}catch(OperationCanceledException){}finally{await p.StopProcessingAsync();await p.DisposeAsync();}}async Task Handle(ProcessMessageEventArgs a){try{var m=JsonSerializer.Deserialize<DocumentProcessed>(a.Message.Body.ToString(),new JsonSerializerOptions(JsonSerializerDefaults.Web))??throw new InvalidOperationException("Invalid processed event");var output=await embeddings.EmbedAsync(m.Chunks,a.CancellationToken);await publisher.PublishAsync(Topics.EmbeddingEvents,new EmbeddingsCreated(Guid.NewGuid(),m.TenantId,m.DocumentId,m.VersionId,output,DateTimeOffset.UtcNow,m.CorrelationId,m.AllowedPrincipalIds),m.CorrelationId,a.CancellationToken);await a.CompleteMessageAsync(a.Message);}catch(Exception ex){log.LogError(ex,"Embedding failed");if(a.Message.DeliveryCount>=5)await a.DeadLetterMessageAsync(a.Message,"max-delivery",ex.Message);else await a.AbandonMessageAsync(a.Message);}}Task Error(ProcessErrorEventArgs e){log.LogError(e.Exception,"Embedding Service Bus error");return Task.CompletedTask;}}